        assert forall |key0| #[trigger] post.frag[key0].is_some() ==> exists |row0, col0|
            0 <= row0 < HEIGHT && 0 <= col0 < WIDTH
                && (#[trigger] post.matrix[row0][col0]).is_some()
                && post.matrix[row0][col0].unwrap().0 == key0 by {
            if !post.frag[key0].is_some() {
            } else if key0 == key {
                assert(post.matrix[row][col as int] === Some((key, new_val)));
                assert(0 <= row && row < HEIGHT && 0 <= col && col < WIDTH);
                assert(exists |r, c| r == row && c == col && 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && post.matrix[r][c].is_some() && post.matrix[r][c].unwrap().0 == key0);
            } else {
                assert(post.frag[key0] == pre.frag[key0]);
                assert(pre.frag[key0].is_some());
                assert(pre.all_distinct());
                assert forall |row0, col0| pre.matrix[row0][col0] == post.matrix[row0][col0] by { };
